 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1220;
         --panel: #121a2b;
         --panel-2: #182235;
         --text: #e5edf9;
         --muted: #9fb0c8;
         --border: #2a3954;
         --accent: #6ea8fe;
         --accent-strong: #8bbcff;
         --error: #ff7a8a;
         --error-bg: rgba(255, 122, 138, 0.12);
         --shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(110, 168, 254, 0.18), transparent 35%),
           linear-gradient(180deg, #09111d, var(--bg));
         color: var(--text);
         display: grid;
         place-items: center;
         padding: 24px;
       }

       main {
         width: min(100%, 760px);
       }

       .card {
         background: linear-gradient(180deg, rgba(24, 34, 53, 0.96), rgba(18, 26, 43, 0.98));
         border: 1px solid rgba(143, 170, 214, 0.14);
         border-radius: 24px;
         box-shadow: var(--shadow);
         overflow: hidden;
       }

       .header {
         padding: 32px 32px 20px;
         border-bottom: 1px solid rgba(143, 170, 214, 0.12);
         background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent);
       }

       h1 {
         margin: 0 0 10px;
         font-size: clamp(1.75rem, 3vw, 2.4rem);
         line-height: 1.1;
       }

       p {
         margin: 0;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         padding: 32px;
       }

       .form-field {
         margin-bottom: 22px;
       }

       label {
         display: inline-block;
         margin-bottom: 8px;
         font-weight: 600;
       }

       input {
         width: 100%;
         padding: 14px 16px;
         border-radius: 14px;
         border: 1px solid var(--border);
         background: var(--panel-2);
         color: var(--text);
         font-size: 1rem;
         outline: none;
         transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
       }

       input::placeholder {
         color: #7f8da6;
       }

       input:focus {
         border-color: var(--accent);
         box-shadow: 0 0 0 4px rgba(110, 168, 254, 0.15);
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
         box-shadow: 0 0 0 4px rgba(255, 122, 138, 0.12);
       }

       .helper-text,
       .error-message {
         display: block;
         margin-top: 8px;
         font-size: 0.92rem;
         line-height: 1.45;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-message {
         color: var(--error);
         min-height: 1.35em;
       }

       .error-message[hidden] {
         display: none;
       }

       .actions {
         margin-top: 8px;
         display: flex;
         justify-content: flex-end;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 14px 22px;
         background: linear-gradient(180deg, var(--accent-strong), var(--accent));
         color: #08111f;
         font-weight: 700;
         font-size: 1rem;
         cursor: pointer;
         box-shadow: 0 14px 30px rgba(110, 168, 254, 0.24);
       }

       button:hover {
         filter: brightness(1.04);
       }

       button:focus {
         outline: 3px solid rgba(255, 255, 255, 0.25);
         outline-offset: 3px;
       }

       @media (max-width: 640px) {
         .header,
         form {
           padding: 22px;
         }

         .actions {
           justify-content: stretch;
         }

         button {
           width: 100%;
         }
       }
     </style>
   </head>
   <body>
     <main>
       <section class="card" aria-labelledby="support-form-title">
         <div class="header">
           <h1 id="support-form-title">Contact support</h1>
           <p>Send us your details and we&apos;ll follow up as soon as possible.</p>
         </div>

         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name</label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               placeholder="Jane Doe"
               required
               aria-describedby="full-name-error"
             />
             <span class="error-message" id="full-name-error" aria-live="polite" hidden></span>
           </div>

           <div class="form-field">
             <label for="email-address">Email address</label>
             <input
               id="email-address"
               name="email"
               type="email"
               autocomplete="email"
               placeholder="jane@example.com"
               required
               aria-describedby="email-address-error"
             />
             <span class="error-message" id="email-address-error" aria-live="polite" hidden></span>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number</label>
             <input
               id="phone-number"
               name="phone"
               type="tel"
               autocomplete="tel"
               placeholder="(555) 123-4567"
               aria-describedby="phone-number-help phone-number-error"
             />
             <span class="helper-text" id="phone-number-help">Optional. Use a format like (555) 123-4567 or 555-123-4567.</span>
             <span class="error-message" id="phone-number-error" aria-live="polite" hidden></span>
           </div>

           <div class="actions">
             <button type="submit">Submit request</button>
           </div>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById("support-form");
       const fullName = document.getElementById("full-name");
       const email = document.getElementById("email-address");
       const phone = document.getElementById("phone-number");

       const fields = [
         {
           input: fullName,
           error: document.getElementById("full-name-error"),
           validate: (value) => {
             if (!value.trim()) return "Full name is required.";
             if (value.trim().length < 2) return "Please enter your full name.";
             return "";
           },
         },
         {
           input: email,
           error: document.getElementById("email-address-error"),
           validate: (value) => {
             if (!value.trim()) return "Email address is required.";
             if (!email.checkValidity()) return "Enter a valid email address.";
             return "";
           },
         },
         {
           input: phone,
           error: document.getElementById("phone-number-error"),
           validate: (value) => {
             if (!value.trim()) return "";

             const pattern = /^(\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4})$/;
             if (!pattern.test(value.trim())) {
               return "Use (555) 123-4567 or 555-123-4567.";
             }
             return "";
           },
         },
       ];

       function setError(field, message) {
         const hasError = Boolean(message);
         field.input.setAttribute("aria-invalid", String(hasError));
         field.error.textContent = message;
         field.error.hidden = !hasError;
       }

       function validateField(field) {
         const message = field.validate(field.input.value);
         setError(field, message);
         return !message;
       }

       fields.forEach((field) => {
         field.input.addEventListener("blur", () => validateField(field));
         field.input.addEventListener("input", () => {
           if (field.error.hidden === false) validateField(field);
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const isValid = fields.map(validateField).every(Boolean);
         if (isValid) {
           form.reset();
           fields.forEach((field) => setError(field, ""));
         }
       });
     </script>
   </body>
 </html>

